class DataManager {
    int internal_data = 0;
public:
    // Standard const function
    int get_data() const { return internal_data; }

    // Use const_cast to provide non-const access to internal data
    // DANGER: Only safe if internal_data is logically mutable
    int& get_mutable_ref() const {
        // Casts 'this' (const DataManager*) to (DataManager*)
        return const_cast<DataManager*>(this)->internal_data;
    }
};

void access_demo() {
    const DataManager cdm;
    // Modifies cdm, bypassing const qualifier
    cdm.get_mutable_ref() = 42;
}
